M = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_PT}): {ac} acusadas. {lac_pt} {PS_PT}"
     f"{RES_PT} A cpw_7 saiu desta leva (a queda em 2001-337 era o erro de convenção da cpv_1, 258ª, corrigido depois desta cadeia; a cpw_7 entra refeita na 260ª, cuja cadeia cobre a correção).")
ME = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_EN}): {ac} caught. {lac_en} {PS_EN}"
      f"{RES_EN} cpw_7 left this batch (the crash in 2001-337 was the cpv_1 calling convention bug, batch 258, fixed after this chain; cpw_7 comes back reworked in batch 260, whose chain covers the fix).")
